input_cols = [
    "Player Name", "Troop ATK", "Troop HP", "Troop DEF", "Troop DMG", "Troop DMG Recv", "Troop ATK Bless", "Troop PROT Bless",
    "Infantry ATK", "Infantry HP", "Infantry DEF", "Infantry DMG", "Infantry DMG Recv", "Infantry ATK Bless", "Infantry PROT Bless",
    "Archer ATK", "Archer HP", "Archer DEF", "Archer DMG", "Archer DMG Recv", "Archer ATK Bless", "Archer PROT Bless",
    "Cav ATK", "Cav HP", "Cav DEF", "Cav DMG", "Cav DMG Recv", "Cav ATK Bless", "Cav PROT Bless",
    "Siege ATK", "Siege HP", "Siege DEF", "Siege DMG", "Siege DMG Recv", "Siege ATK Bless", "Siege PROT Bless", "Lethal %"
]

with open('master_database.csv', 'r', encoding='utf-8') as f:
    master_header = f.readline().strip().split(',')

reader = csv.DictReader(io.StringIO(raw_data), fieldnames=input_cols)

with open('master_database.csv', 'a', encoding='utf-8', newline='') as f:
    writer = csv.DictWriter(f, fieldnames=master_header)
    for row in reader:
        name = row['Player Name']
        server = 'K277' if name.startswith('(277)') else 'K27'
        row['Server'] = server
        row['Player Name'] = name
        
        # Strip all plus signs and percent signs like in the other records if needed,
        # but the master database seems to hold strings with % based on the previous scripts.
        # Actually looking at K162_All_Stats.csv they don't have plus signs. The user prompt did.
        # I will strip the plus signs to keep it consistent.
        for k, v in row.items():
            if type(v) == str:
                row[k] = v.replace('+', '')
        
        writer.writerow(row)

print("K27/K277 appended successfully!")
